import { test } from 'node:test';
import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
const script = new URL('../stats.js', import.meta.url).pathname;
const run = (...a) => spawnSync(process.execPath, [script, ...a], { encoding: 'utf8' });
test('plain output unchanged', () => assert.equal(run('3', '1', '4').stdout, 'count 3\nmean 2.6666666666666665\nmin 1\nmax 4\n'));
test('json anywhere', () => {
  assert.deepEqual(JSON.parse(run('--json', '2', '4').stdout), { count: 2, mean: 3, min: 2, max: 4 });
  assert.deepEqual(JSON.parse(run('2', '--json', '4').stdout), { count: 2, mean: 3, min: 2, max: 4 });
});
test('no numbers', () => { const r = run('--json'); assert.equal(r.status, 1); assert.ok(r.stderr.length > 0); });

solution.stats.js:
const args = process.argv.slice(2);
const json = args.includes('--json');
const nums = args.filter((a) => a !== '--json').map(Number);
if (nums.length === 0) {
  console.error('give me some numbers');
  process.exit(1);
}
const count = nums.length;
const mean = nums.reduce((a, b) => a + b, 0) / count;
const min = Math.min(...nums);
const max = Math.max(...nums);
if (json) console.log(JSON.stringify({ count, mean, min, max }));
else {
  console.log(`count ${count}`);
  console.log(`mean ${mean}`);
  console.log(`min ${min}`);
  console.log(`max ${max}`);
}
